<script setup lang="ts">import type{CoverConfig}from'../../core/models';defineProps<{config:CoverConfig;title:string;editing?:boolean}>();const emit=defineEmits<{patch:[p:Partial<CoverConfig>];title:[t:string];save:[];replace:[f:File]}>();function pick(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(file)emit('replace',file)}</script>
<template><section class="cover-layout"><div class="stage-card controls"><span class="kicker">04 / COVER LAB</span><h2>给声音穿件有戏的外套</h2><label>作品名称<input :value="title" @input="emit('title',($event.target as HTMLInputElement).value)"></label><label>气泡文字<textarea aria-label="气泡文字" :value="config.bubbleText" @input="emit('patch',{bubbleText:($event.target as HTMLTextAreaElement).value})"></textarea></label><label>滤镜<select :value="config.filter" @change="emit('patch',{filter:($event.target as HTMLSelectElement).value as CoverConfig['filter']})"><option value="none">原色</option><option value="mono">黑白</option><option value="saturate">高饱和</option><option value="warm">暖调</option><option value="cool">冷调</option></select></label><label>比例<select :value="config.ratio" @change="emit('patch',{ratio:($event.target as HTMLSelectElement).value as CoverConfig['ratio']})"><option value="square">方形 1:1</option><option value="portrait">竖版 3:4</option></select></label><label v-if="editing" class="replace-voice">替换声音（名称与气泡会保留）<input type="file" accept="audio/*" data-testid="replace-file" @change="pick"></label><button data-testid="save-work" class="acid-button" type="button" @click="emit('save')">保存作品</button></div><div class="cover-preview" :class="[config.ratio,config.filter]" :style="{'--c1':config.palette[0],'--c2':config.palette[1],'--c3':config.palette[2]}"><span>SOUND REACTION / 005</span><div class="burst"></div><h3>{{ config.title }}</h3><p>{{ config.bubbleText }}</p><i>▶ PLAY IT</i></div></section></template>
